INSERT INTO `classes` (`id`, `num`, `name`, `hit_die`, `primary_ability`, `role`, `caster`, `data`) VALUES
  ('warden', 1, 'WARDEN', 10, 'STR', 'tank', NULL, '{"name":"WARDEN","hd":10,"primary":"STR","saves":["STR","CON"],"armor":["light","medium","heavy","shield"],"weapons":"martial","caster":null,"skills":["athletics","perception"],"gear":["longbrand","chainhauberk","buckler"],"role":"tank","features":[[1,"style_def"],[1,"secondwind"],[2,"surge"],[5,"extra1"],[9,"indomitable"],[11,"extra2"],[17,"surge2"],[20,"extra3"]],"subs":[{"id":"champion","name":"CHAMPION","keys":{"critRange":1},"desc":"Crit on 19-20."},{"id":"tactician","name":"TACTICIAN","keys":{"maneuver":1},"desc":"+1d8 on first hit each turn (4/rest)."}],"desc":"Masters of arms and armour. Second wind, action surge, many attacks."}'),
  ('berserker', 2, 'BERSERKER', 12, 'STR', 'tank', NULL, '{"name":"BERSERKER","hd":12,"primary":"STR","saves":["STR","CON"],"armor":["light","medium","shield"],"weapons":"martial","caster":null,"skills":["athletics","survival"],"gear":["widesword","hidecoat"],"role":"tank","features":[[1,"rage"],[1,"unarmored_con"],[2,"reckless"],[5,"extra1"],[9,"brutal"]],"subs":[{"id":"frenzy","name":"FRENZY","keys":{"frenzy":1},"desc":"Extra attack while raging."},{"id":"totem","name":"TOTEM","keys":{"totem":1},"desc":"Resist all damage while raging."}],"desc":"Fury made flesh. Rage halves weapon damage taken."}'),
  ('vanguard', 3, 'VANGUARD', 10, 'STR', 'tank', 'half', '{"name":"VANGUARD","hd":10,"primary":"STR","saves":["WIS","CHA"],"armor":["light","medium","heavy","shield"],"weapons":"martial","caster":"half","cast":"CHA","skills":["religion","persuasion"],"gear":["ironhammer","chainhauberk","buckler"],"role":"tank","features":[[1,"layhands"],[2,"style_def"],[2,"smite"],[5,"extra1"],[6,"aura"],[11,"brightsmite"]],"subs":[{"id":"devotion","name":"DEVOTION","keys":{"sacred":1},"desc":"+CHA to hit (channel, 1/rest)."},{"id":"vengeance","name":"VENGEANCE","keys":{"vow":1},"desc":"Advantage vs your sworn foe."}],"desc":"Oathsworn knights. Smite with spell slots, heal by touch."}'),
  ('strider', 4, 'STRIDER', 10, 'DEX', 'dps', 'half', '{"name":"STRIDER","hd":10,"primary":"DEX","saves":["STR","DEX"],"armor":["light","medium","shield"],"weapons":"martial","caster":"half","cast":"WIS","skills":["survival","stealth"],"gear":["greatbow","scalevest"],"role":"dps","features":[[1,"favored"],[2,"style_arch"],[5,"extra1"]],"subs":[{"id":"hunter","name":"HUNTER","keys":{"colossus":1},"desc":"+1d8 vs wounded foes."},{"id":"beastmaster","name":"BEASTMASTER","keys":{"wolf":1},"desc":"A wolf fights beside you."}],"desc":"Wilderness hunters. Bows, marks and nature magic."}'),
  ('shade', 5, 'SHADE', 8, 'DEX', 'dps', NULL, '{"name":"SHADE","hd":8,"primary":"DEX","saves":["DEX","INT"],"armor":["light"],"weapons":"finesse","caster":null,"skills":["stealth","sleight","acrobatics","perception"],"expertise":["stealth","perception"],"gear":["needleblade","quilted"],"role":"dps","features":[[1,"sneak"],[2,"cunning"],[5,"uncanny"],[7,"evasion"],[11,"reliable"]],"subs":[{"id":"thief","name":"THIEF","keys":{"fasthands":1},"desc":"Use items as a bonus action."},{"id":"assassin","name":"ASSASSIN","keys":{"assassinate":1},"desc":"Auto-crit foes that have not acted."}],"desc":"Knives in the dark. Sneak attack and slippery tricks."}'),
  ('ascetic', 6, 'ASCETIC', 8, 'DEX', 'dps', NULL, '{"name":"ASCETIC","hd":8,"primary":"DEX","saves":["STR","DEX"],"armor":[],"weapons":"simple","caster":null,"skills":["acrobatics","insight"],"gear":["walkstaff"],"role":"dps","features":[[1,"martial"],[1,"unarmored_wis"],[2,"ki"],[5,"extra1"],[5,"stunning"],[7,"evasion"]],"subs":[{"id":"openhand","name":"OPEN HAND","keys":{"openhand":1},"desc":"Flurry knocks foes prone."},{"id":"shadow","name":"SHADOW","keys":{"shadowstart":1},"desc":"Begin fights unseen."}],"desc":"Monks of the still mind. Fists, ki and stunning blows."}'),
  ('arcanist', 7, 'ARCANIST', 6, 'INT', 'dps', 'full', '{"name":"ARCANIST","hd":6,"primary":"INT","saves":["INT","WIS"],"armor":[],"weapons":"simple","caster":"full","cast":"INT","skills":["arcana","history"],"gear":["walkstaff"],"role":"dps","features":[[1,"recovery"]],"subs":[{"id":"evoker","name":"EVOKER","keys":{"evoker":1},"desc":"+INT to STORM spell damage."},{"id":"abjurer","name":"ABJURER","keys":{"ward":1},"desc":"Arcane ward of temp HP each fight."}],"desc":"Scholars of the eight schools. The widest spell list."}'),
  ('wildblood', 8, 'WILDBLOOD', 6, 'CHA', 'dps', 'full', '{"name":"WILDBLOOD","hd":6,"primary":"CHA","saves":["CON","CHA"],"armor":[],"weapons":"simple","caster":"full","cast":"CHA","skills":["arcana","intimidation"],"gear":["knife"],"role":"dps","features":[[2,"sorcery"],[3,"quicken"]],"subs":[{"id":"draconic","name":"DRACONIC","keys":{"draconic":1},"desc":"AC 13+DEX, +CHA fire damage."},{"id":"surge","name":"WILD SURGE","keys":{"wildsurge":1},"desc":"Spells may surge with bonus effects."}],"desc":"Magic in the blood. Sorcery points bend spells."}'),
  ('pactbound', 9, 'PACTBOUND', 8, 'CHA', 'dps', 'pact', '{"name":"PACTBOUND","hd":8,"primary":"CHA","saves":["WIS","CHA"],"armor":["light"],"weapons":"simple","caster":"pact","cast":"CHA","skills":["arcana","deception"],"gear":["knife","quilted"],"role":"dps","features":[[1,"hexbolt"],[2,"agonizing"],[11,"arcanum"]],"subs":[{"id":"fiend","name":"FIEND PACT","keys":{"fiend":1},"desc":"Temp HP when you kill."},{"id":"archfey","name":"ARCHFEY","keys":{"feypresence":1},"desc":"Charm all foes (1/rest)."}],"desc":"Bargainers with strange patrons. Few slots, back each short rest."}'),
  ('cantor', 10, 'CANTOR', 8, 'CHA', 'healer', 'full', '{"name":"CANTOR","hd":8,"primary":"CHA","saves":["DEX","CHA"],"armor":["light"],"weapons":"simple","caster":"full","cast":"CHA","skills":["performance","persuasion","insight"],"gear":["needleblade","quilted"],"role":"healer","features":[[1,"inspire"],[2,"restsong"],[2,"jack"]],"subs":[{"id":"lore","name":"LORE","keys":{"cutting":1},"desc":"Cutting words blunt enemy hits."},{"id":"valor","name":"VALOR","keys":{"valor":1},"desc":"Extra attack at level 6."}],"desc":"Songweavers. Inspire allies, heal, and charm."}'),
  ('chaplain', 11, 'CHAPLAIN', 8, 'WIS', 'healer', 'full', '{"name":"CHAPLAIN","hd":8,"primary":"WIS","saves":["WIS","CHA"],"armor":["light","medium","shield"],"weapons":"simple","caster":"full","cast":"WIS","skills":["religion","medicine"],"gear":["knobmace","scalevest","buckler"],"role":"healer","features":[[2,"channel"],[5,"destroyundead"]],"subs":[{"id":"life","name":"LIFE","keys":{"lifedomain":1},"desc":"Heals restore +2+slot level."},{"id":"tempest","name":"TEMPEST","keys":{"tempest":1},"desc":"Max lightning/thunder damage (channel)."}],"desc":"Priests of the Lantern. Healing, wards, and turning the dead."}'),
  ('verdant', 12, 'VERDANT', 8, 'WIS', 'healer', 'full', '{"name":"VERDANT","hd":8,"primary":"WIS","saves":["INT","WIS"],"armor":["light","medium","shield"],"weapons":"simple","caster":"full","cast":"WIS","skills":["nature","animal"],"gear":["walkstaff","hidecoat"],"role":"healer","features":[[2,"wildshape"]],"subs":[{"id":"moon","name":"MOON","keys":{"moon":1},"desc":"Stronger beast shapes."},{"id":"land","name":"LAND","keys":{"landrecover":1},"desc":"Recover slots on short rest."}],"desc":"Keepers of the green. Beast shapes and nature spells."}'),
  ('necromancer', 13, 'NECROMANCER', 6, 'INT', 'dps', 'full', '{"name":"NECROMANCER","hd":6,"primary":"INT","saves":["INT","WIS"],"armor":[],"weapons":"simple","caster":"full","cast":"INT","skills":["arcana","medicine"],"gear":["walkstaff"],"role":"dps","features":[[1,"recovery"]],"subs":[{"id":"gravecaller","name":"GRAVECALLER","keys":{"fiend":1},"desc":"Claim vitality when you defeat an enemy."},{"id":"boneweaver","name":"BONEWEAVER","keys":{"ward":1},"desc":"Gain a protective arcane ward each fight."}],"desc":"Wield grave magic, drain life, and command the power of death."}'),
  ('summoner', 14, 'SUMMONER', 8, 'CHA', 'dps', 'full', '{"name":"SUMMONER","hd":8,"primary":"CHA","saves":["CON","CHA"],"armor":["light"],"weapons":"simple","caster":"full","cast":"CHA","skills":["arcana","animal"],"gear":["walkstaff","quilted"],"role":"dps","features":[[1,"recovery"]],"subs":[{"id":"spiritcaller","name":"SPIRITCALLER","keys":{"wolf":1},"desc":"Call a spirit companion to fight at your side."},{"id":"wardbinder","name":"WARDBINDER","keys":{"ward":1},"desc":"Protect yourself with a ward at the start of battle."}],"desc":"Bind spirits and call allies from beyond the veil."}'),
  ('sunwarden', 15, 'SUNWARDEN', 10, 'WIS', 'healer', 'half', '{"name":"SUNWARDEN","hd":10,"primary":"WIS","saves":["WIS","CHA"],"armor":["light","medium","shield"],"weapons":"martial","caster":"half","cast":"WIS","skills":["religion","athletics"],"gear":["ironhammer","scalevest","buckler"],"role":"healer","features":[[1,"layhands"],[5,"extra1"]],"subs":[{"id":"dawnkeeper","name":"DAWNKEEPER","keys":{"lifedomain":1},"desc":"Restore more health with healing spells."},{"id":"sunstriker","name":"SUNSTRIKER","keys":{"sacred":1},"desc":"Invoke sacred power to empower your weapon."}],"desc":"Guardians of the dawn who heal allies and burn foes with radiant light."}'),
  ('runeblade', 16, 'RUNEBLADE', 10, 'STR', 'tank', 'half', '{"name":"RUNEBLADE","hd":10,"primary":"STR","saves":["STR","CON"],"armor":["light","medium","heavy"],"weapons":"martial","caster":"half","cast":"CHA","skills":["athletics","intimidation"],"gear":["widesword","chainhauberk"],"role":"tank","features":[[1,"rage"],[5,"extra1"]],"subs":[{"id":"bloodrune","name":"BLOOD RUNE","keys":{"totem":1},"desc":"Withstand damage through dark runic power."},{"id":"frostbrand","name":"FROST BRAND","keys":{"maneuver":1},"desc":"Unleash a practiced runic strike."}],"desc":"A rune-armored death knight who mixes martial strength with dark magic."}'),
  ('ronin', 17, 'RONIN', 10, 'STR', 'dps', NULL, '{"name":"RONIN","hd":10,"primary":"STR","saves":["STR","DEX"],"armor":["light","medium"],"weapons":"martial","caster":null,"skills":["athletics","intimidation"],"gear":["widesword","scalevest"],"role":"dps","features":[[1,"style_def"],[2,"surge"],[5,"extra1"],[11,"extra2"]],"subs":[{"id":"kensai","name":"KENSAI","keys":{"critRange":1},"desc":"Crit on 19-20."},{"id":"iaido","name":"IAIDO","keys":{"maneuver":1},"desc":"+1d8 on first hit each turn (4/rest)."}],"desc":"Wandering blade masters. Meditate, then cut with a single perfect stroke."}'),
  ('shinobi', 18, 'SHINOBI', 8, 'DEX', 'dps', NULL, '{"name":"SHINOBI","hd":8,"primary":"DEX","saves":["DEX","INT"],"armor":["light"],"weapons":"finesse","caster":null,"skills":["stealth","acrobatics","sleight"],"expertise":["stealth"],"gear":["needleblade","quilted"],"role":"dps","features":[[1,"cunning"],[5,"extra1"]],"subs":[{"id":"kage","name":"KAGE","keys":{"shadowstart":1},"desc":"Start every battle invisible."},{"id":"yamikiri","name":"YAMIKIRI","keys":{"assassinate":1},"desc":"Strike hard before foes act."}],"desc":"Shadow warriors. Paper-image decoys and spinning shuriken."}'),
  ('bladedancer', 19, 'BLADEDANCER', 8, 'DEX', 'healer', NULL, '{"name":"BLADEDANCER","hd":8,"primary":"DEX","saves":["DEX","CHA"],"armor":["light"],"weapons":"finesse","caster":null,"skills":["performance","acrobatics","persuasion"],"gear":["knife","quilted"],"role":"healer","features":[[1,"cunning"],[5,"extra1"]],"subs":[{"id":"veil","name":"VEIL DANCER","keys":{"ward":1},"desc":"Start battles with a ward."},{"id":"edge","name":"EDGE DANCER","keys":{"critRange":1},"desc":"Crit on 19-20."}],"desc":"Dancers whose steps heal friends and unbalance foes."}'),
  ('wyrmlancer', 20, 'WYRMLANCER', 10, 'STR', 'dps', NULL, '{"name":"WYRMLANCER","hd":10,"primary":"STR","saves":["STR","CON"],"armor":["light","medium","heavy"],"weapons":"martial","caster":null,"skills":["athletics","animal"],"gear":["poleblade","chainhauberk"],"role":"dps","features":[[1,"style_def"],[5,"extra1"],[9,"indomitable"]],"subs":[{"id":"skyleap","name":"SKYLEAP","keys":{"critRange":1},"desc":"Crit on 19-20."},{"id":"wyrmbond","name":"WYRMBOND","keys":{"wolf":1},"desc":"A wyvern hatchling fights beside you."}],"desc":"Lancers who leap from the sky with a wyvern at their side."}'),
  ('corsair', 21, 'CORSAIR', 8, 'DEX', 'dps', NULL, '{"name":"CORSAIR","hd":8,"primary":"DEX","saves":["DEX","CHA"],"armor":["light"],"weapons":"martial","caster":null,"skills":["deception","acrobatics","perception"],"gear":["boltcaster","quilted"],"role":"dps","features":[[1,"style_arch"],[5,"extra1"]],"subs":[{"id":"fortune","name":"FORTUNE","keys":{"critRange":1},"desc":"Crit on 19-20."},{"id":"quickdraw","name":"QUICKDRAW","keys":{"maneuver":1},"desc":"+1d8 on first hit each turn (4/rest)."}],"desc":"Lucky gunners. Phantom dice for the party, elemental shots for foes."}'),
  ('beastcaller', 22, 'BEASTCALLER', 10, 'CHA', 'tank', NULL, '{"name":"BEASTCALLER","hd":10,"primary":"CHA","saves":["STR","CHA"],"armor":["light","medium","shield"],"weapons":"martial","caster":null,"skills":["animal","survival"],"gear":["hatchet","hidecoat","buckler"],"role":"tank","features":[[1,"style_def"],[5,"extra1"]],"subs":[{"id":"packlord","name":"PACKLORD","keys":{"wolf":1},"desc":"A wolf joins every battle."},{"id":"feral","name":"FERAL","keys":{"frenzy":1},"desc":"Fight like a beast: an extra attack in a frenzy."}],"desc":"Tamers who fight with the wild at their back."}'),
  ('puppeteer', 23, 'PUPPETEER', 8, 'INT', 'tank', NULL, '{"name":"PUPPETEER","hd":8,"primary":"INT","saves":["DEX","INT"],"armor":["light"],"weapons":"simple","caster":null,"skills":["arcana","sleight"],"gear":["cudgel","quilted"],"role":"tank","features":[[1,"reliable"],[5,"extra1"]],"subs":[{"id":"valoredge","name":"VALOREDGE","keys":{"ward":1},"desc":"Start battles with a ward."},{"id":"sharpshot","name":"SHARPSHOT FRAME","keys":{"critRange":1},"desc":"Crit on 19-20."}],"desc":"Engineers with a clockwork automaton that shields and strikes."}'),
  ('dreadknight', 24, 'DREADKNIGHT', 10, 'STR', 'tank', 'half', '{"name":"DREADKNIGHT","hd":10,"primary":"STR","saves":["STR","CON"],"armor":["light","medium","heavy"],"weapons":"martial","caster":"half","cast":"INT","skills":["athletics","intimidation"],"gear":["widesword","chainhauberk"],"role":"tank","features":[[1,"style_def"],[2,"secondwind"],[5,"extra1"]],"subs":[{"id":"bloodoath","name":"BLOOD OATH","keys":{"vow":1},"desc":"Vow of enmity against one foe."},{"id":"frostgrave","name":"FROSTGRAVE","keys":{"totem":1},"desc":"Resist all damage while raging."}],"desc":"Knights who returned from the grave. They steal life and hold foes in place."}'),
  ('voidhunter', 25, 'VOIDHUNTER', 10, 'DEX', 'dps', NULL, '{"name":"VOIDHUNTER","hd":10,"primary":"DEX","saves":["DEX","CON"],"armor":["light","medium"],"weapons":"martial","caster":null,"skills":["perception","acrobatics","intimidation"],"gear":["crescent","scalevest"],"role":"dps","features":[[1,"style_def"],[5,"extra1"],[11,"extra2"]],"subs":[{"id":"havoc","name":"HAVOC","keys":{"frenzy":1},"desc":"An extra attack in a frenzy."},{"id":"vengeance","name":"VENGEANCE","keys":{"totem":1},"desc":"Resist all damage while raging."}],"desc":"Blindfolded hunters who sacrificed their sight to see the void."}'),
  ('scalesage', 26, 'SCALESAGE', 8, 'INT', 'healer', 'full', '{"name":"SCALESAGE","hd":8,"primary":"INT","saves":["INT","CHA"],"armor":["light"],"weapons":"simple","caster":"full","cast":"INT","skills":["arcana","medicine"],"gear":["walkstaff","quilted"],"role":"healer","features":[[1,"recovery"]],"subs":[{"id":"devastation","name":"DEVASTATION","keys":{"evoker":1},"desc":"Spell damage adds your INT."},{"id":"preservation","name":"PRESERVATION","keys":{"lifedomain":1},"desc":"Healing spells heal more."}],"desc":"Dragon-blooded sages. Breath of fire for foes, emerald light for friends."}'),
  ('stormcaller', 27, 'STORMCALLER', 8, 'WIS', 'healer', 'half', '{"name":"STORMCALLER","hd":8,"primary":"WIS","saves":["WIS","CHA"],"armor":["light","medium","shield"],"weapons":"simple","caster":"half","cast":"WIS","skills":["nature","medicine"],"gear":["knobmace","scalevest","buckler"],"role":"healer","features":[[1,"layhands"],[5,"extra1"]],"subs":[{"id":"thunder","name":"THUNDER","keys":{"tempest":1},"desc":"Lightning and thunder hit harder."},{"id":"tides","name":"TIDES","keys":{"lifedomain":1},"desc":"Healing spells heal more."}],"desc":"Shamans who plant totems and call the storm."}');
INSERT INTO `species` (`id`, `num`, `name`, `data`) VALUES
  ('hearthkin', 1, 'HEARTHKIN', '{"name":"HEARTHKIN","asi":{"STR":1,"DEX":1,"CON":1,"INT":1,"WIS":1,"CHA":1},"traits":["versatile"],"desc":"Common folk of the river towns. +1 to all abilities, extra skill."}'),
  ('thornelf', 2, 'THORNELF', '{"name":"THORNELF","asi":{"DEX":2,"WIS":1},"traits":["keen","feyblood"],"desc":"Long-lived forest kin. Keen senses; resist charm and sleep."}'),
  ('stonekin', 3, 'STONEKIN', '{"name":"STONEKIN","asi":{"CON":2,"STR":1},"traits":["stoneblood"],"res":["poison"],"desc":"Mountain delvers. Resist poison; advantage on poison saves."}'),
  ('wispling', 4, 'WISPLING', '{"name":"WISPLING","asi":{"DEX":2,"CHA":1},"traits":["lucky","brave"],"desc":"Small and lucky. Reroll natural 1s; advantage vs fear."}'),
  ('emberborn', 5, 'EMBERBORN', '{"name":"EMBERBORN","asi":{"CHA":2,"INT":1},"traits":["emberbolt"],"res":["fire"],"desc":"Touched by old fire. Resist fire; know EMBERDART."}'),
  ('burrowkin', 6, 'BURROWKIN', '{"name":"BURROWKIN","asi":{"INT":2,"CON":1},"traits":["cunning"],"desc":"Clever tunnel folk. Advantage on INT/WIS/CHA saves against magic."}'),
  ('twinblood', 7, 'TWINBLOOD', '{"name":"TWINBLOOD","asi":{"CHA":2,"DEX":1,"CON":1},"traits":["feyblood","versatile"],"desc":"Born of two peoples. Resist charm; an extra skill."}'),
  ('tuskborn', 8, 'TUSKBORN', '{"name":"TUSKBORN","asi":{"STR":2,"CON":1},"traits":["relentless"],"desc":"Fierce and hardy. Once per rest, drop to 1 HP instead of 0."}'),
  ('drakkin', 9, 'DRAKKIN', '{"name":"DRAKKIN","asi":{"STR":2,"CHA":1},"traits":["breath"],"res":["fire"],"desc":"Dragon-blooded. Fire breath once per rest; resist fire."}'),
  ('hornfolk', 10, 'HORNFOLK', '{"name":"HORNFOLK","asi":{"STR":2,"CON":1},"traits":["stalwart","warstomp"],"desc":"Horned giants of the plains. Extra health; WAR STOMP stuns foes once a battle."}'),
  ('felinar', 11, 'FELINAR', '{"name":"FELINAR","asi":{"DEX":2,"WIS":1},"traits":["keen","nimble"],"desc":"Swift cat-folk. Keen senses and +5% dodge."}'),
  ('pipkin', 12, 'PIPKIN', '{"name":"PIPKIN","asi":{"INT":2,"DEX":1},"traits":["cunning","spellspark"],"desc":"Small, bright spellcasters. +10% elemental damage; resist magic."}'),
  ('lunari', 13, 'LUNARI', '{"name":"LUNARI","asi":{"DEX":2,"INT":1},"traits":["feyblood","shadowmeld"],"desc":"Moon elves. Begin battles hidden; resist charm and sleep."}'),
  ('wolfkin', 14, 'WOLFKIN', '{"name":"WOLFKIN","asi":{"STR":2,"DEX":1},"traits":["feral"],"desc":"Wolf-blooded hunters. +4% crit chance and +15% crit damage."}'),
  ('starkin', 15, 'STARKIN', '{"name":"STARKIN","asi":{"WIS":2,"CHA":1},"traits":["lightsgift"],"res":["radiant"],"desc":"Light-touched travellers. +15% healing; GIFT OF LIGHT heals once a battle."}');
