  ('scholar', 2, 'SCHOLAR', 10, '{"name":"SCHOLAR","skills":["arcana","history"],"gold":10,"desc":"You studied in the Ardenhold archives."}'),
  ('wanderer', 3, 'WANDERER', 10, '{"name":"WANDERER","skills":["survival","perception"],"gold":10,"desc":"You grew up on the open road."}'),
  ('urchin', 4, 'URCHIN', 8, '{"name":"URCHIN","skills":["stealth","sleight"],"gold":8,"desc":"You learned the alleys of Ardenhold."}'),
  ('acolyte', 5, 'ACOLYTE', 12, '{"name":"ACOLYTE","skills":["religion","insight"],"gold":12,"desc":"You tended the Lantern shrines."}'),
  ('envoy', 6, 'ENVOY', 20, '{"name":"ENVOY","skills":["persuasion","deception"],"gold":20,"desc":"You spoke for a noble house."}');
